package com.medcore.backend.api.internaciones;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/internaciones")public class InternacionController{private final InternacionService service;public InternacionController(InternacionService service){this.service=service;}@PostMapping@PreAuthorize("hasAnyRole('ADMIN','MEDICO','ENFERMERIA')")public ResponseEntity<InternacionResponse>crear(@Valid@RequestBody InternacionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(r));}@GetMapping public Page<InternacionResponse>listar(@PageableDefault(size=20,sort="id")Pageable p){return service.listar(p);}@GetMapping("/{id}")public InternacionResponse obtener(@PathVariable Long id){return service.obtener(id);}@PatchMapping("/{id}/alta")@PreAuthorize("hasRole('MEDICO')")public InternacionResponse alta(@PathVariable Long id){return service.alta(id);}}
